insert into cases (site_id, klantnaam, sector, resultaat_periode, uitdaging, citaat, schakels, foto, published, sort_order) values ('22222222-2222-2222-2222-222222222222', 'Aurora Pavilion', 'BELEVING', '2026', 'Wat als een gebouw niet alleen een plek is, maar ook een verhaal dat je binnenstapt?', 'Een ruimte krijgt betekenis door wat mensen erin ervaren.', array['Conceptontwikkeling','Ruimtelijk ontwerp','Storytelling','Beeldregie']::text[], '/media/hero_arch.webp', true, 1);
insert into cases (site_id, klantnaam, sector, resultaat_periode, uitdaging, citaat, schakels, foto, published, sort_order) values ('22222222-2222-2222-2222-222222222222', 'Lumen Experience', 'CULTUUR', '2026', 'Een ruimte zonder vast verhaal. Tot de bezoeker begint te bewegen.', 'Je hoeft een ervaring niet te begrijpen om er iets bij te voelen.', array['Belevingsconcept','Lichtregie','Ruimtelijk ontwerp','Bezoekersreis']::text[], '/media/work_color.webp', true, 2);
insert into cases (site_id, klantnaam, sector, resultaat_periode, uitdaging, citaat, schakels, foto, published, sort_order) values ('22222222-2222-2222-2222-222222222222', 'Echo Spaces', 'ONTWERP', '2025', 'Soms is het meest opvallende aan een ruimte wat je weglaat.', 'Goede ruimtes laten mensen de hoofdrol spelen.', array['Interieurconcept','Ruimtelijk ontwerp','Materialisatie','Gebruikersonderzoek']::text[], '/media/work_arch.webp', true, 3);
insert into cases (site_id, klantnaam, sector, resultaat_periode, uitdaging, citaat, schakels, foto, published, sort_order) values ('22222222-2222-2222-2222-222222222222', 'Pulse Festival', 'EVENEMENT', '2026', 'Drie dagen waarin nieuwe ideeën niet alleen besproken, maar ook beleefd worden.', 'Een sterk evenement begint niet bij het podium, maar bij de ontmoeting.', array['Eventconcept','Programmaontwikkeling','Visuele identiteit','Communicatie']::text[], '/media/event_lights.webp', true, 4);
insert into cases (site_id, klantnaam, sector, resultaat_periode, uitdaging, citaat, schakels, foto, published, sort_order) values ('22222222-2222-2222-2222-222222222222', 'Future Assembly', 'TECHNOLOGIE', '2026', 'Technologie verandert wat we kunnen. Mensen bepalen waarom het ertoe doet.', 'De interessantste ideeën komen zelden van één persoon.', array['Programmaconcept','Workshops','Community','Eventdesign']::text[], '/media/journal_event.webp', true, 5);
insert into cases (site_id, klantnaam, sector, resultaat_periode, uitdaging, citaat, schakels, foto, published, sort_order) values ('22222222-2222-2222-2222-222222222222', 'The Atrium', 'RUIMTE', '2025', 'Licht, lucht en genoeg vrijheid om een bijeenkomst eigen te maken.', 'De beste ruimte laat iedereen op zijn gemak binnenkomen.', array['Ruimteconcept','Inrichting','Gastbeleving','Eventopstellingen']::text[], '/media/space_atrium.webp', true, 6);
insert into teamleden (site_id, naam, functie, tekst, foto, published, sort_order) values ('22222222-2222-2222-2222-222222222222', 'Maya Chen', 'Creatief directeur', 'Maya verbindt ideeën, beeld en gevoel. Ze zoekt naar het bijzondere in alledaagse vragen. Bij NOVA onderzoekt Maya hoe een ontwerp mensen iets kan laten voelen. Ze gelooft in scherpe keuzes, duidelijke verhalen en genoeg ruimte voor het onverwachte. Ze is een fictief teamlid in deze CMS-demonstratie.', '/media/comm_face.webp', true, 1);
insert into teamleden (site_id, naam, functie, tekst, foto, published, sort_order) values ('22222222-2222-2222-2222-222222222222', 'Noah Vermeer', 'Hoofd belevingen', 'Noah denkt in routes, ritme en ontmoetingen. Voor hem is een ervaring pas geslaagd als bezoekers zelf iets ontdekken. Noah vertaalt ideeën naar programma’s en ruimtelijke beleving. Van eerste ontvangst tot laatste gesprek kijkt hij naar het geheel. Noah is een fictief profiel.', '/media/comm_man.webp', true, 2);
insert into teamleden (site_id, naam, functie, tekst, foto, published, sort_order) values ('22222222-2222-2222-2222-222222222222', 'Amara Brooks', 'Ontwerpstrateeg', 'Amara stelt graag de vraag achter de vraag. Daar vindt ze vaak het begin van een beter idee. Amara combineert onderzoek en creativiteit. Ze zoekt naar de verbinding tussen behoeften, merkverhaal en vorm. Dit is een fictief demoprofiel.', '/media/journal_face.webp', true, 3);
insert into teamleden (site_id, naam, functie, tekst, foto, published, sort_order) values ('22222222-2222-2222-2222-222222222222', 'Luca Moreno', 'Communitycurator', 'Luca brengt mensen samen die elkaar anders misschien nooit hadden ontmoet. Luca bouwt ontmoetingen met aandacht voor sfeer, toegankelijkheid en oprechte nieuwsgierigheid. Luca is een fictieve maker voor de NOVA-website.', '/media/comm_person.webp', true, 4);
insert into partners (site_id, naam, slug, branche, tagline, over_tekst, quote, uitgelicht, published, sort_order) values ('22222222-2222-2222-2222-222222222222', 'Atelier North', 'atelier-north', 'Ruimtelijk ontwerp', 'Fictieve ontwerpstudio die architectuur, licht en menselijke beleving bij elkaar brengt.', 'Fictieve ontwerpstudio die architectuur, licht en menselijke beleving bij elkaar brengt.', 'Mooie dingen ontstaan als werelden elkaar ontmoeten.', true, true, 1);
insert into partners (site_id, naam, slug, branche, tagline, over_tekst, uitgelicht, published, sort_order) values ('22222222-2222-2222-2222-222222222222', 'Common Ground Lab', 'common-ground-lab', 'Community & onderzoek', 'Fictief collectief dat nieuwe manieren van samenwerken onderzoekt.', 'Fictief collectief dat nieuwe manieren van samenwerken onderzoekt.', false, true, 2);
insert into partners (site_id, naam, slug, branche, tagline, over_tekst, uitgelicht, published, sort_order) values ('22222222-2222-2222-2222-222222222222', 'Signal Works', 'signal-works', 'Technologie & media', 'Fictieve creatieve technologiestudio met liefde voor eenvoudige, heldere toepassingen.', 'Fictieve creatieve technologiestudio met liefde voor eenvoudige, heldere toepassingen.', false, true, 3);
